insert into public.norma_dispositivos (norma, artigo, texto, recorte, fonte_url, observacao) values ($t$LEI_14133_2021$t$, 57, $t$Art. 57. O edital de licitação poderá estabelecer intervalo mínimo de diferença de valores entre os lances, que incidirá tanto em relação aos lances intermediários quanto em relação à proposta que cobrir a melhor oferta.$t$, null, $t$https://www.legjur.com/legislacao/art/lei_00141332021-57$t$, null)
